class Solution {
public:
    vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values, vector<vector<string>>& queries) {
        unordered_map<string, unordered_map<string, double>> graph;
        for (size_t i = 0; i < equations.size(); ++i) {
            const string& u = equations[i][0];
            const string& v = equations[i][1];
            double val = values[i];
            graph[u][v] = val;
            graph[v][u] = 1.0 / val;
        }
        auto bfs = [&](const string& src, const string& dst) -> double {
            if (!graph.count(src) || !graph.count(dst)) return -1.0;
            if (src == dst) return 1.0;
            queue<pair<string, double>> q;
            unordered_set<string> visited;
            q.push({src, 1.0});
            visited.insert(src);
            while (!q.empty()) {
                auto [curr, prod] = q.front();
                q.pop();
                if (curr == dst) return prod;
                for (const auto& [neighbor, weight] : graph[curr]) {
                    if (!visited.count(neighbor)) {
                        visited.insert(neighbor);
                        q.push({neighbor, prod * weight});
                    }
                }
            }
            return -1.0;
        };
        vector<double> res;
        for (const auto& q : queries) {
            res.push_back(bfs(q[0], q[1]));
        }
        return res;
    }
};

class Solution {
    public double[] calcEquation(List<List<String>> equations, double[] values, List<List<String>> queries) {
        Map<String, Map<String, Double>> graph = new HashMap<>();
        for (int i = 0; i < equations.size(); i++) {
            String u = equations.get(i).get(0);
            String v = equations.get(i).get(1);
            double val = values[i];
            graph.computeIfAbsent(u, k -> new HashMap<>()).put(v, val);
            graph.computeIfAbsent(v, k -> new HashMap<>()).put(u, 1.0 / val);
        }
        double[] res = new double[queries.size()];
        for (int i = 0; i < queries.size(); i++) {
            res[i] = bfs(graph, queries.get(i).get(0), queries.get(i).get(1));
        }
        return res;
    }
    private double bfs(Map<String, Map<String, Double>> graph, String src, String dst) {
        if (!graph.containsKey(src) || !graph.containsKey(dst)) return -1.0;
        if (src.equals(dst)) return 1.0;
        Queue<Pair> q = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        q.add(new Pair(src, 1.0));
        visited.add(src);
        while (!q.isEmpty()) {
            Pair curr = q.poll();
            if (curr.node.equals(dst)) return curr.prod;
            for (Map.Entry<String, Double> entry : graph.get(curr.node).entrySet()) {
                if (!visited.contains(entry.getKey())) {
                    visited.add(entry.getKey());
                    q.add(new Pair(entry.getKey(), curr.prod * entry.getValue()));
                }
            }
        }
        return -1.0;
    }
    private static class Pair {
        String node;
        double prod;
        Pair(String node, double prod) { this.node = node; this.prod = prod; }
    }
}

var calcEquation = function(equations, values, queries) {
    const graph = new Map();
    for (let i = 0; i < equations.length; i++) {
        const [u, v] = equations[i];
        const val = values[i];
        if (!graph.has(u)) graph.set(u, new Map());
        if (!graph.has(v)) graph.set(v, new Map());
        graph.get(u).set(v, val);
        graph.get(v).set(u, 1.0 / val);
    }
    const bfs = (src, dst) => {
        if (!graph.has(src) || !graph.has(dst)) return -1.0;
        if (src === dst) return 1.0;
        const q = [[src, 1.0]];
        const visited = new Set([src]);
        let head = 0;
        while (head < q.length) {
            const [curr, prod] = q[head++];
            if (curr === dst) return prod;
            for (const [neighbor, weight] of graph.get(curr).entries()) {
                if (!visited.has(neighbor)) {
                    visited.add(neighbor);
                    q.push([neighbor, prod * weight]);
                }
            }
        }
        return -1.0;
    };
    return queries.map(([c, d]) => bfs(c, d));
};
